// Push gate: decides whether the agent may send a push to a user right now.
// Rules, checked in this order:
//   1. quiet hours (user's local clock, may span midnight)  -> "quiet_hours"
//   2. daily cap (user's local calendar day, not 24h rolling) -> "daily_cap_reached"
//   3. minimum gap between pushes (no bursts)               -> "too_soon_after_last_push"
// Bad input fails closed (no push): "invalid_time", "invalid_user_settings".

const MIN_GAP_MS = 30 * 60 * 1000;
const KEEP_MS = 3 * 24 * 60 * 60 * 1000; // enough to cover any local day in any zone

const formatters = new Map();
function formatterFor(timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
    formatters.set(timeZone, f); // throws RangeError on an unknown zone, before caching
  }
  return f;
}

// Local wall-clock parts of a UTC instant in the given zone.
function localParts(ms, timeZone) {
  const p = {};
  for (const { type, value } of formatterFor(timeZone).formatToParts(ms)) p[type] = value;
  return {
    dayKey: `${p.year}-${p.month}-${p.day}`,
    minutes: Number(p.hour) * 60 + Number(p.minute),
  };
}

function parseHHMM(s) {
  const m = typeof s === 'string' ? /^([01]\d|2[0-3]):([0-5]\d)$/.exec(s) : null;
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

function inQuietHours(minutes, start, end) {
  if (start === end) return false; // empty window: no quiet period
  return start < end
    ? minutes >= start && minutes < end
    : minutes >= start || minutes < end; // runs past midnight
}

export function createPushGate() {
  const sent = new Map(); // user id -> ascending array of send times (ms)

  return {
    attempt(user, now) {
      const nowMs = now instanceof Date ? now.getTime() : NaN;
      if (!Number.isFinite(nowMs)) return { allowed: false, reason: 'invalid_time' };

      const start = parseHHMM(user?.quietStart);
      const end = parseHHMM(user?.quietEnd);
      const cap = user?.dailyCap;
      if (
        typeof user?.id !== 'string' || start === null || end === null ||
        !Number.isInteger(cap) || cap < 0
      ) {
        return { allowed: false, reason: 'invalid_user_settings' };
      }

      let today;
      try {
        today = localParts(nowMs, user.timeZone);
      } catch {
        return { allowed: false, reason: 'invalid_user_settings' };
      }

      if (inQuietHours(today.minutes, start, end)) {
        return { allowed: false, reason: 'quiet_hours' };
      }

      const history = (sent.get(user.id) ?? []).filter((t) => nowMs - t < KEEP_MS);
      sent.set(user.id, history);

      // Only pushes at or before now count; a caller clock that steps back must not undercount.
      const countToday = history.filter(
        (t) => localParts(t, user.timeZone).dayKey === today.dayKey,
      ).length;
      if (countToday >= cap) return { allowed: false, reason: 'daily_cap_reached' };

      const last = history.length ? history[history.length - 1] : null;
      if (last !== null && Math.abs(nowMs - last) < MIN_GAP_MS) {
        return { allowed: false, reason: 'too_soon_after_last_push' };
      }

      history.push(nowMs);
      history.sort((a, b) => a - b);
      return { allowed: true, reason: null };
    },
  };
}

import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/baseline-g2-2/bot.mjs';

const tokyo = { id: 'u1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const d = (s) => new Date(s);
let g = createPushGate();

// Tokyo = UTC+9. 12:00 JST = 03:00Z
assert.deepEqual(g.attempt(tokyo, d('2026-03-10T03:00:00Z')), { allowed: true, reason: null });
// 23:30 JST (14:30Z) quiet, 06:59 JST (21:59Z prev day) quiet, 07:00 JST ok
assert.equal(g.attempt(tokyo, d('2026-03-10T14:30:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(tokyo, d('2026-03-10T21:59:00Z')).reason, 'quiet_hours');
// gap
assert.equal(g.attempt(tokyo, d('2026-03-10T03:10:00Z')).reason, 'too_soon_after_last_push');
assert.equal(g.attempt(tokyo, d('2026-03-10T04:00:00Z')).allowed, true);
assert.equal(g.attempt(tokyo, d('2026-03-10T05:00:00Z')).allowed, true);
// cap of 3 reached (rejections didn't count)
assert.equal(g.attempt(tokyo, d('2026-03-10T06:00:00Z')).reason, 'daily_cap_reached');
// next local day starts 15:00Z; 22:00 JST is quiet till 07:00 JST (22:00Z) -> then allowed
assert.equal(g.attempt(tokyo, d('2026-03-10T22:00:00Z')).allowed, true);
// local midnight rollover, not UTC: 23:30Z = 08:30 JST next day, fresh day
const g2 = createPushGate();
const noQuiet = { ...tokyo, quietStart: '03:00', quietEnd: '03:00', dailyCap: 1 };
assert.equal(g2.attempt(noQuiet, d('2026-03-10T14:50:00Z')).allowed, true); // 23:50 JST
assert.equal(g2.attempt(noQuiet, d('2026-03-10T15:40:00Z')).allowed, true); // 00:40 JST next day
assert.equal(g2.attempt(noQuiet, d('2026-03-10T17:00:00Z')).reason, 'daily_cap_reached');
// same-day window, DST zone (New York spring forward 2026-03-08)
const ny = { id: 'n', timeZone: 'America/New_York', quietStart: '01:00', quietEnd: '06:00', dailyCap: 5 };
const g3 = createPushGate();
assert.equal(g3.attempt(ny, d('2026-03-08T06:30:00Z')).reason, 'quiet_hours'); // 01:30 EST
assert.equal(g3.attempt(ny, d('2026-03-08T09:30:00Z')).reason, 'quiet_hours'); // 05:30 EDT
assert.equal(g3.attempt(ny, d('2026-03-08T10:00:00Z')).allowed, true); // 06:00 EDT
// independence
assert.equal(createPushGate().attempt(tokyo, d('2026-03-10T04:00:00Z')).allowed, true);
// bad input
assert.equal(g.attempt({ ...tokyo, timeZone: 'Nope/Zone' }, d('2026-03-10T03:00:00Z')).reason, 'invalid_user_settings');
assert.equal(g.attempt(tokyo, new Date(NaN)).reason, 'invalid_time');
assert.equal(createPushGate().attempt({ ...tokyo, dailyCap: 0 }, d('2026-03-10T03:00:00Z')).reason, 'daily_cap_reached');
console.log('ok');
